// CERT Skills Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: SALT triage decisions, bleeding control and safe search and rescue.
import {q, mix} from './q.js';
const CERT='FEMA CERT Basic Training Participant Manual / IS-317', FAST='American Red Cross, First Aid for Severe Trauma (FAST)', SALT='SALT Mass Casualty Triage (NDLSF)';
const PREP='Disaster Preparedness', ORG='CERT Organization', LTI='Life Threatening Interventions and SALT Triage', MED='Medical Operations', PSY='Disaster Psychology', FIRE='Fire Safety', SAR='Light Search and Rescue Operations', TER='Terrorism';

export default {
 id:'cert-skills-1',
 event:'CERT Skills',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'the FEMA CERT Basic Training Participant Manual (IS-317), American Red Cross FAST and SALT Mass Casualty Triage',
 plan:[{area:PREP,weight:15},{area:ORG,weight:5},{area:LTI,weight:30},{area:MED,weight:20},{area:PSY,weight:5},{area:FIRE,weight:5},{area:SAR,weight:15},{area:TER,weight:5}],
 questions:mix([
  q(PREP,'Officials announce a chemical release nearby and tell residents to shelter in place. What should you do?','Go in, close windows, stop ventilation',['Open windows to air out the house','Drive toward the release to check it','Go outside and wait for buses'],'B','Sheltering in place keeps contaminated air out. Choose an interior room, seal gaps if instructed and listen for updates.',CERT),
  q(PREP,'How much water should a household store per person per day for emergencies?','1 gallon',['1 cup','1 quart','5 gallons'],'D','Store at least 1 gallon per person per day for drinking and sanitation, for at least 3 days (longer is better).',CERT),
  q(PREP,'What is the recommended action during an earthquake if you are indoors?','Drop, cover and hold on',['Run outside immediately','Stand in a doorway','Stand next to a window'],'A','Dropping to the ground, taking cover under sturdy furniture and holding on protects you from falling objects. Most injuries happen from falling or flying debris.',CERT),
  q(PREP,'Where is the safest place to shelter during a tornado?','An interior room on the lowest floor',['An upstairs bedroom with windows','A car parked on the highway','Under a highway overpass'],'C','A basement or small interior room on the lowest floor puts as many walls as possible between you and the storm.',CERT),
  q(PREP,'Why should you never walk or drive through flowing floodwater?','Shallow moving water can sweep you away',['Floodwater is always warm','Floodwater always moves very slowly','It is only dangerous at night'],'B','About 6 inches of moving water can knock an adult down, and about 12 inches can carry away a car. “Turn around, don’t drown.”',CERT),
  q(PREP,'When should the natural gas be turned off at the meter after a disaster?','Only if you smell or hear gas',['Every time there is a storm','Never, under any circumstances','Every night as a precaution'],'D','Once gas is shut off, only the utility company should turn it back on. Turn it off only if there is a suspected leak.',CERT),
  q(PREP,'Why should a family communication plan include an out-of-area contact?','Distant calls may connect when local lines jam',['Local contacts are not allowed to help','It is required by federal law','Out-of-area contacts must pick up family members'],'A','Family members can each check in with the same distant contact to share where they are and that they are safe. Text messages may also get through when calls do not.',CERT),
  q(PREP,'Which home hazard mitigation step helps prevent injuries and fires during an earthquake?','Strapping the water heater to wall studs',['Hanging heavy pictures over beds','Storing heavy items on high shelves','Keeping cabinets unlatched'],'C','Securing water heaters and tall furniture, latching cabinets and storing heavy items low reduce injuries and gas leaks.',CERT),
  q(ORG,'Which management system do CERTs use to organize their response?','The Incident Command System',['The START system','The Glasgow system','The SAMPLE system'],'B','ICS gives a common structure, terminology and chain of command so CERTs can work with fire, police and EMS.',CERT),
  q(ORG,'What is the highest priority for every CERT member during an operation?','The rescuer’s own safety',['Saving the most property','Finding all victims quickly','Clearing roads for traffic'],'D','A rescuer who is injured becomes another victim. CERT members size up the scene and never take risks beyond their training.',CERT),
  q(ORG,'In ICS, the recommended span of control for one supervisor is about:','3 to 7 people',['1 person','10 to 15 people','20 or more people'],'A','A manageable span of control keeps communication and supervision effective.',CERT),
  q(LTI,'What do the letters in SALT triage stand for?','Sort, Assess, Lifesave, Treat/Transport',['Search, Alert, Lift, Transport, Track','Scan, Airway, Look, Treat','Size up, Act, Lead, Track'],'C','SALT begins with global sorting, then individual assessment, quick lifesaving interventions and decisions about treatment or transport.',SALT),
  q(LTI,'In the SALT global sort, which group is assessed first?','Those still or with obvious life threats',['People who can walk','People who wave or move purposefully','People who are crying loudly'],'B','Victims are asked to walk to a location, then to wave. Those who remain still, or have obvious life threats, are assessed first.',SALT),
  q(LTI,'Which is a lifesaving intervention in SALT triage?','Controlling major bleeding',['Splinting a broken finger','Bandaging a minor scrape','Taking a full medical history'],'D','SALT lifesaving interventions are quick and within scope: controlling major hemorrhage, opening the airway, chest decompression and auto-injector antidotes.',SALT),
  q(LTI,'In SALT, which tag color is used for a patient categorized as expectant?','Gray',['Green','Yellow','Red'],'A','Expectant patients are unlikely to survive with current resources and are reassessed when resources allow. Immediate is red, delayed yellow, minimal green and dead black.',SALT),
  q(LTI,'In SALT, a patient with only minor injuries who can be cared for later is categorized as:','Minimal',['Immediate','Delayed','Expectant'],'C','Minimal (green) patients have minor injuries. Delayed (yellow) patients have serious injuries but can wait for care.',SALT),
  q(LTI,'Where should a tourniquet be placed for severe bleeding from the lower leg?','2–3 inches above the wound',['Directly over the wound','Below the wound, toward the foot','Over the knee joint'],'B','The tourniquet goes between the wound and the heart, avoiding joints. Tighten until bleeding stops and note the time.',FAST),
  q(LTI,'A deep wound in the groin is bleeding heavily. A tourniquet cannot be used. What should be done?','Pack it and press firmly',['Apply an ice pack only','Raise the leg and wait','Leave it uncovered'],'D','Junctional wounds are packed tightly with gauze (or hemostatic dressing) and held with firm, direct pressure.',FAST),
  q(LTI,'What are the “three killers” that CERT members are taught to address first?','Airway blockage, bleeding and shock',['Fractures, burns and sprains','Hypothermia, dehydration and hunger','Headache, nausea and dizziness'],'A','These conditions can cause death within minutes, so they are treated before other injuries.',CERT),
  q(LTI,'How does a CERT member open the airway of an unresponsive adult with no suspected spinal injury?','Head tilt–chin lift',['Pull the tongue forward with fingers','Sweep the mouth blindly','Turn the head sharply to the side'],'C','The head tilt–chin lift moves the tongue away from the back of the throat. Check for breathing after opening the airway.',CERT),
  q(LTI,'Which finding suggests a victim is in shock?','Capillary refill longer than 2 seconds',['A slow pulse with warm, dry skin','Capillary refill under 1 second','Calm, alert speech'],'B','Signs include rapid, shallow breathing, capillary refill over 2 seconds and inability to follow simple commands.',CERT),
  q(LTI,'What is the blanch test used for?','Checking circulation in a nail bed',['Testing for broken bones','Measuring body temperature','Checking pupils for brain injury'],'D','Color should return in about 2 seconds. A longer delay suggests poor perfusion and possible shock.',CERT),
  q(LTI,'How is a victim in shock usually positioned by CERT members if there are no contraindications?','On the back, feet slightly raised',['Sitting upright against a wall','Face down','Standing and walking'],'A','The CERT manual teaches raising the feet slightly and keeping the victim warm, while watching breathing and avoiding movement if spinal injury is suspected.',CERT),
  q(LTI,'What is usually the first method used to control bleeding?','Direct pressure on the wound',['A tourniquet on every wound','Pouring water on the wound','Leaving the wound open to air'],'C','Firm, direct pressure stops most bleeding. Tourniquets are used for life-threatening limb bleeding that pressure does not control.',FAST),
  q(LTI,'After applying a tourniquet, what should the CERT member record?','The time it was applied',['The patient’s favorite color','The brand of gauze used','The weather conditions'],'B','The time helps hospital staff decide on treatment. A tourniquet is not loosened in the field.',FAST),
  q(LTI,'In SALT, which quick intervention may be given to a child who is not breathing after the airway is opened?','Two rescue breaths',['Five back blows','Chest compressions for 10 minutes','Nothing; the child is tagged dead'],'A','Children are more likely than adults to have a breathing-related arrest, so SALT allows two rescue breaths before categorizing.',SALT),
  q(MED,'How is a CERT medical treatment area usually organized?','By priority: immediate, delayed, minor',['One large area with no divisions','By the victims’ last names','By the time each victim arrives'],'C','Separating victims by priority helps rescuers direct limited resources and track patients.',CERT),
  q(MED,'In what order is a head-to-toe assessment done?','Head, neck, torso, pelvis, then limbs',['Legs first, then arms, head and chest','Chest only, then the head if time allows','Any order the rescuer prefers'],'B','A systematic order helps ensure no injury is missed. Rescuers look, listen and feel for injuries while watching for spinal injury signs.',CERT),
  q(MED,'How much unscented household bleach is used to disinfect 1 gallon of clear water when boiling is not possible?','About 1/8 teaspoon',['1 cup','About 1/2 gallon','No bleach is safe'],'D','Stir and let the water stand for 30 minutes; it should have a slight chlorine smell. Cloudy water needs filtering and more bleach.',CERT),
  q(MED,'When splinting a suspected fracture, what should the splint immobilize?','The joints above and below the injury',['Only the injured spot','The entire body','Nothing; splints are not used'],'A','Immobilizing the joints on either side keeps the bone ends from moving. Check circulation, sensation and movement before and after splinting.',CERT),
  q(MED,'What is the first step in caring for a burn after removing the victim from the source?','Cool the burn with cool water',['Apply butter','Break any blisters','Cover it with cotton balls'],'C','Cool water stops the burning process and reduces pain. Then cover loosely with a clean, dry dressing.',CERT),
  q(MED,'Why should CERT members change gloves between victims?','To prevent spreading infection between victims',['To keep their hands warm','Because gloves expire every minute','To make documentation easier'],'B','Body fluids on gloves can carry infection to the next victim. Gloves, goggles and masks protect both rescuers and victims.',CERT),
  q(MED,'A victim pulled from cold water is shivering and confused. What should CERT members do?','Remove wet clothing and warm the victim gradually',['Rub the arms and legs vigorously','Give the victim alcohol','Place the victim directly in hot water'],'D','Handle hypothermic victims gently, remove wet clothing and use blankets to warm the core. Rough handling can cause heart problems.',CERT),
  q(MED,'A victim found under debris complains of neck pain. What should CERT members do?','Keep the head, neck and spine in line',['Have the victim sit up to check movement','Turn the head side to side','Lift the victim by the arms'],'A','Suspected spinal injuries are stabilized in line. Move the victim only if the scene is unsafe, using a backboard or several rescuers.',CERT),
  q(MED,'A victim has a piece of glass impaled in the forearm. What should be done?','Stabilize it in place with bulky dressings',['Pull it out quickly','Push it deeper to stop bleeding','Cut it flush with the skin'],'C','Removing an impaled object can cause severe bleeding. It is stabilized and the victim is transported for care.',CERT),
  q(MED,'What information should be recorded for each victim treated?','Injuries, treatment and destination',['Only the victim’s first name','Only the time of day','Nothing; there is no time to document'],'B','Documentation helps track victims and treatment and supports the handoff to professional responders.',CERT),
  q(PSY,'A survivor is shaking and crying after a disaster. What is the best CERT response?','Listen and connect them to support',['Tell the survivor to stop crying','Ignore the survivor’s feelings','Force the survivor to describe every detail'],'D','Psychological first aid focuses on safety, calm, connection and practical help. Strong emotions are normal reactions to an abnormal event.',CERT),
  q(PSY,'How can CERT team leaders reduce stress among rescuers during a long operation?','Rotate assignments and schedule rest breaks',['Keep everyone working without breaks','Assign the same worker to the hardest task all day','Discourage talking about the experience'],'A','Rest, rotation, hydration and talking with others help prevent burnout. Team leaders watch for signs of stress.',CERT),
  q(FIRE,'Which class of fire involves flammable liquids such as gasoline or oil?','Class B',['Class A','Class C','Class D'],'C','Class A involves ordinary combustibles, Class B flammable liquids, Class C energized electrical equipment, and Class D combustible metals.',CERT),
  q(FIRE,'What does the PASS method for using a fire extinguisher stand for?','Pull, Aim, Squeeze, Sweep',['Push, Alert, Spray, Stop','Point, Activate, Shake, Spray','Pull, Alert, Spray, Smother'],'B','Pull the pin, aim at the base of the fire, squeeze the handle and sweep side to side.',CERT),
  q(FIRE,'When should CERT members NOT attempt to put out a fire?','When the fire is spreading beyond where it started',['When it is in a small wastebasket','When they have the right extinguisher','When they have two ways to exit'],'D','CERT members fight only small fires with a clear exit and backup. Larger fires are left to the fire department.',CERT),
  q(SAR,'A CERT search team finds a building with obvious structural damage, such as leaning walls. What should the team do?','Stay out and mark the building',['Enter quickly to search for victims','Climb onto the roof to look inside','Use a car to push the walls back'],'A','CERT members may enter only lightly damaged buildings. Heavily damaged buildings are left to trained urban search and rescue teams.',CERT),
  q(SAR,'Which rule is used when lifting heavy debris with a lever and cribbing?','Lift an inch, crib an inch',['Lift as high as possible at once','Never use cribbing','Lift the debris with your back'],'C','Adding cribbing as the object rises keeps it stable and prevents it from falling back onto the victim or rescuers.',CERT),
  q(SAR,'Why do CERT search teams always use the buddy system?','So no rescuer works alone',['To carry more equipment','To search twice as fast as one person','To avoid filling out forms'],'B','Working in pairs ensures someone can call for help or assist if a rescuer is injured or trapped.',CERT),
  q(SAR,'During a search, after calling out, what should rescuers do next?','Stop and listen for responses',['Keep shouting without pausing','Leave the building','Turn on loud equipment'],'D','Rescuers call out, then stay quiet and listen for tapping or voices, which helps locate trapped victims.',CERT),
  q(SAR,'What do CERT searchers draw on a building to show it has been searched?','A large X with details',['A circle around the door','A check mark on the window','A star on the roof'],'A','The search marking records the team, time and date, hazards and number of victims found, so others do not duplicate the search.',CERT),
  q(SAR,'A conscious victim with no serious injuries can help move. Which removal method is appropriate?','Assisting the victim to walk out',['A blanket drag','Leaving the victim inside','A two-person cradle carry with the spine twisted'],'C','The least invasive method that is safe is used. Victims who cannot walk may be moved with drags or carries.',CERT),
  q(SAR,'Which search pattern helps a team systematically cover every room in a building?','Right-wall or left-wall search',['Random search','Searching only the first room','Searching only from outside'],'B','Following one wall around each room and floor ensures nothing is missed and helps searchers find their way out.',CERT),
  q(TER,'Several people at an event suddenly have trouble breathing and watery eyes, and nearby birds are dead. What should CERT members suspect?','A chemical attack',['A normal heat wave','A food allergy','A power outage'],'D','Many people with the same symptoms and dead animals suggest a chemical release. Leave the area, move upwind and notify authorities.',CERT),
  q(TER,'After an explosion, why should CERT members be cautious about rushing to the scene?','There may be secondary devices targeting responders',['Explosions never cause injuries','Police do not want help','The scene is always safe after one blast'],'A','Terrorists may plant a second device to harm responders. CERT members stay back, report and follow directions from officials.',CERT)
 ],139)
};
